export function FitnessPage(props:WorkspaceActions & {kind:'fitness'|'cs2'}){const {snapshot,refresh,report,kind}=props;const edit=useEditor(props);const [tab,setTab]=useState<WorkspaceKind>(kind==='cs2'?'cs2logs':'gym');const [query,setQuery]=useState('');const [advice,setAdvice]=useState('');const [loading,setLoading]=useState(false);const [saveProfile,setSaveProfile]=useState(!snapshot.preferences.fitness.currentWeight||!snapshot.preferences.fitness.height);const [goal,setGoal]=useState(snapshot.preferences.fitness.goal);const [experience,setExperience]=useState(snapshot.preferences.fitness.experience);const [constraints,setConstraints]=useState(snapshot.preferences.fitness.constraints);const [weight,setWeight]=useState(String(snapshot.preferences.fitness.currentWeight||''));const [height,setHeight]=useState(String(snapshot.preferences.fitness.height||''));
 const [age,setAge]=useState(String(snapshot.preferences.fitness.age||''));const [activity,setActivity]=useState(snapshot.preferences.fitness.activity||'moderate');const [weeklyDays,setWeeklyDays]=useState(String(snapshot.preferences.fitness.weeklyDays||3));
 const [equipment,setEquipment]=useState(snapshot.preferences.fitness.homeEquipment||'Доріжка');
 const [cs2Goals,setCs2Goals]=useState(snapshot.preferences.cs2Targets);
 const [photoResult,setPhotoResult]=useState<{title:string;calories:number|null;protein:number|null;note:string;photoData:string}|null>(null);
 const [analyzingPhoto,setAnalyzingPhoto]=useState(false);
 useEffect(()=>{setTab(kind==='cs2'?'cs2logs':'gym');},[kind]);const logs=snapshot.workspace[tab]||[];const tabs:({id:WorkspaceKind;label:string})[]=kind==='fitness'?[{id:'gym',label:'Домашні тренування'},{id:'cardio',label:'Кардіо / доріжка'},{id:'meals',label:'Харчування'},{id:'weight',label:'Вага / заміри'},{id:'programs',label:'Програми'}]:[{id:'cs2logs',label:'CS2-журнал'}];
 async function profile(){try{await window.lifehub.setPreferences({fitness:{...snapshot.preferences.fitness,goal,experience,constraints,currentWeight:weight?Number(weight):null,height:height?Number(height):null,age:age?Number(age):null,activity,weeklyDays:Number(weeklyDays)||3,homeEquipment:equipment}});await refresh();report('Спортивний профіль збережено');setSaveProfile(false);}catch(e){report(String(e));}}
 async function askAI(){if(!query.trim()){report('Напиши запит до AI');return;}setLoading(true);try{const r=await window.lifehub.aiInsight(tab==='meals'?'nutrition':'fitness',query);setAdvice(r.text);await refresh();}catch(e){report(String(e));}finally{setLoading(false);}}
 async function analyzePhoto(){setAnalyzingPhoto(true);try{const result=await window.lifehub.analyzeFoodPhoto();if(result)setPhotoResult(result);await refresh();}catch(e){report(e instanceof Error?e.message:String(e));}finally{setAnalyzingPhoto(false);}}
 async function savePhotoMeal(){if(!photoResult)return;try{await window.lifehub.addWorkspace('meals',{title:photoResult.title,date:nowDate(),calories:photoResult.calories,protein:photoResult.protein,note:photoResult.note,photoData:photoResult.photoData});await refresh();setPhotoResult(null);report('Запис про харчування збережено');}catch(e){report(String(e));}}
 async function savePreset(title:string,content:string,focus:string){try{await window.lifehub.addWorkspace('programs',{title,date:nowDate(),focus,content});await refresh();setTab('programs');report('Шаблон додано до програм. Налаштуй його під свій стан.');}catch(e){report(String(e));}}
 async function saveCs2Targets(){try{await window.lifehub.setPreferences({cs2Targets:cs2Goals});await refresh();report('CS2-цілі збережено');}catch(e){report(String(e));}}
 const cs2Today=snapshot.workspace.cs2logs.filter(x=>x.date===nowDate());
 const cs2Sum=(key:string)=>cs2Today.reduce((sum,x)=>sum+(Number(x[key])||0),0);
 async function saveAdvice(){try{await window.lifehub.addWorkspace('programs',{title:tab==='meals'?'План харчування від AI':'Тренувальний план від AI',date:nowDate(),focus:tab==='meals'?'nutrition':tab==='cardio'?'cardio':'gym',content:advice});await refresh();report('AI-пропозицію збережено до «Програми»');setAdvice('');}catch(e){report(String(e));}}
 const recent=snapshot.workspace.weight.filter(x=>x.kg!==null).slice().sort((a,b)=>fieldText(a,'date').localeCompare(fieldText(b,'date'))).slice(-8);
 return <div className="hub-workspace"><PageHeading label={kind==='fitness'?'HEALTH / FITNESS':'PERFORMANCE / ESPORTS'} title={kind==='fitness'?'Фізична форма · вдома':'CS2 · Тренування'} subtitle={kind==='fitness'?'Домашні вправи, доріжка, харчування й заміри — у твоєму темпі.':'Відстежуй DM, ботів, матчі та тривалість занять без обов’язкового AI.'} action={<button className="button primary" onClick={()=>edit.open(tab)}><Plus size={16}/> Новий запис</button>}/>
 <div className="hub-tabs">{tabs.map(t=><button key={t.id} onClick={()=>setTab(t.id)} className={tab===t.id?'active':''}>{t.label}</button>)}</div>
 {kind==='fitness'&&<section className="hub-surface hub-profile"><div className="hub-section-head"><div><h2>Спочатку — твої параметри</h2><p>Внеси дані один раз; потім їх можна буде редагувати. Дані зберігаються локально; AI бачить їх тільки під час твого запиту.</p></div><button className="hub-soft-button" onClick={()=>setSaveProfile(!saveProfile)}><SlidersHorizontal size={15}/> {saveProfile?'Згорнути':'Редагувати параметри'}</button></div>{saveProfile?<div className="hub-profile-form"><label>Ціль<select value={goal} onChange={e=>setGoal(e.target.value)}><option value="general">Загальна форма</option><option value="loss">Зниження ваги</option><option value="muscle">Набір м’язів</option><option value="endurance">Витривалість</option></select></label><label>Досвід<select value={experience} onChange={e=>setExperience(e.target.value)}><option value="beginner">Початківець</option><option value="intermediate">Середній</option><option value="advanced">Досвідчений</option></select></label><label>Вік (за бажанням)<input type="number" min="1" max="110" value={age} onChange={e=>setAge(e.target.value)}/></label><label>Рівень щоденної активності<select value={activity} onChange={e=>setActivity(e.target.value)}><option value="low">Малорухливий</option><option value="moderate">Помірний</option><option value="high">Активний</option></select></label><label>Днів на тиждень<input type="number" min="1" max="7" value={weeklyDays} onChange={e=>setWeeklyDays(e.target.value)}/></label><label>Обладнання вдома<input value={equipment} onChange={e=>setEquipment(e.target.value)} maxLength={200}/></label><label>Вага (кг)<input type="number" step="0.1" value={weight} onChange={e=>setWeight(e.target.value)}/></label><label>Зріст (см)<input type="number" value={height} onChange={e=>setHeight(e.target.value)}/></label><label className="wide">Обмеження / травми / доступне обладнання<textarea value={constraints} onChange={e=>setConstraints(e.target.value)} rows={3}/></label><button className="button primary" onClick={()=>void profile()}><Save size={16}/> Зберегти профіль</button></div>:<div className="hub-profile-summary"><span>Ціль: <strong>{{general:'Форма',loss:'Схуднення',muscle:'М’язи',endurance:'Витривалість'}[snapshot.preferences.fitness.goal]||'Загальна'}</strong></span><span>Остання записана вага: <strong>{recent.at(-1)?.kg?`${recent.at(-1)?.kg} кг`:'—'}</strong></span><span>Тренувань: <strong>{snapshot.workspace.gym.length+snapshot.workspace.cardio.length}</strong></span></div>}</section>}
 {kind==='fitness'&&<section className="hub-surface hub-presets"><div className="hub-section-head"><div><h2>Програми для дому без API</h2><p>Приклади для адаптації під свої можливості — не медичні призначення.</p></div></div><div className="hub-preset-grid"><button className="hub-soft-button" onClick={()=>void savePreset('Стартова домашня програма', '3 рази на тиждень за самопочуттям: 5 хв легкої розминки, 2×8 присідань до стільця, 2×8 віджимань від стіни, 2×10 сідничного мосту, 5 хв розтяжки. Збільшувати поступово, якщо комфортно.', 'general')}>+ Стартові вправи</button><button className="hub-soft-button" onClick={()=>void savePreset('Доріжка — легкий темп', 'Почни із 15–20 хв легкої ходьби на доріжці 3–4 рази на тиждень. Поступово змінюй тривалість лише за комфортного самопочуття. Не прив’язуй до спалення їжі.', 'cardio')}>+ Доріжка · старт</button><button className="hub-soft-button" onClick={()=>void savePreset('Основа харчування', 'Регулярні прийоми їжі, білок і овочі за можливості, достатньо питної води; різноманітність та зручні порції. Калорійність індивідуальна, не визначати дефіцит без даних.', 'nutrition')}>+ Основи харчування</button></div></section>}
 {kind==='cs2'&&<section className="hub-surface hub-cs2-goals"><div className="hub-section-head"><div><h2>Мої цілі на сьогодні</h2><p>Прогрес рахується із записів CS2-журналу за поточну дату.</p></div></div><div className="hub-cs2-goal-grid">{([{key:'dmKills',label:'DM-фраги'},{key:'botKills',label:'Боти'},{key:'matches',label:'Матчі'},{key:'minutes',label:'Хвилини'}] as const).map(g=>{const amount=g.key==='minutes'?cs2Sum('duration'):cs2Sum(g.key),target=cs2Goals[g.key]||1;return <div className="hub-cs2-goal" key={g.key}><label>{g.label}<input type="number" min="1" value={cs2Goals[g.key]} onChange={e=>setCs2Goals(old=>({...old,[g.key]:Number(e.target.value)||0}))}/></label><strong>{amount} / {target}</strong><div className="task-meter-track"><span style={{width:`${Math.min(100,amount/target*100)}%`}}/></div></div>})}</div><button className="button outline" onClick={()=>void saveCs2Targets()}><Save size={15}/> Зберегти цілі</button><p className="hub-footnote">Можна вести 500 фрагів DM, 1000 ботів, 5 матчів — редагуй цілі. Аналіз .dem — окрема майбутня інтеграція; сама нейромережа не читає демку без спеціального парсера.</p></section>}
 {kind==='fitness'&&tab==='meals'&&<section className="hub-surface hub-food-photo"><div className="hub-section-head"><div><h2>Фото страви → оцінка AI</h2><p>Вибери фото з ПК. Перед збереженням перевір назву, порцію та приблизну калорійність.</p></div><button className="button primary" disabled={!snapshot.hasKey||analyzingPhoto} onClick={()=>void analyzePhoto()}><Plus size={15}/> {analyzingPhoto?'Аналіз…':'Аналізувати фото'}</button></div>{!snapshot.hasKey&&<p className="hub-notice">Потрібен API-ключ. Звичайний журнал їжі безкоштовний.</p>}{photoResult&&<div className="hub-photo-result"><img src={photoResult.photoData} alt="Обрана страва"/><div><label className="hub-field"><span>Назва страви</span><input value={photoResult.title} onChange={e=>setPhotoResult(old=>old?{...old,title:e.target.value}:old)}/></label><div className="hub-photo-values"><label className="hub-field"><span>Калорії (оцінка)</span><input type="number" min="0" value={photoResult.calories??''} onChange={e=>setPhotoResult(old=>old?{...old,calories:e.target.value?Number(e.target.value):null}:old)}/></label><label className="hub-field"><span>Білок, г (оцінка)</span><input type="number" min="0" value={photoResult.protein??''} onChange={e=>setPhotoResult(old=>old?{...old,protein:e.target.value?Number(e.target.value):null}:old)}/></label></div><label className="hub-field"><span>Примітка / порція</span><textarea rows={2} value={photoResult.note} onChange={e=>setPhotoResult(old=>old?{...old,note:e.target.value}:old)}/></label><div className="hub-tool-row"><button className="button primary" onClick={()=>void savePhotoMeal()}>Додати в журнал</button><button className="button outline" onClick={()=>setPhotoResult(null)}>Відхилити</button></div></div></div>}<small>Оцінка лише за фото може суттєво помилятися. Остаточний запис робиш ти.</small></section>}
 <div className="hub-grid hub-training-layout"><section className="hub-surface"><div className="hub-section-head"><div><h2>{tabs.find(x=>x.id===tab)?.label}</h2><p>{logs.length} записів · ручний журнал</p></div><button className="hub-icon-button" onClick={()=>edit.open(tab)}><Plus size={17}/></button></div><CardRows items={logs} render={x=><>{Boolean(x.photoData)&&<img className="hub-meal-thumb" src={fieldText(x,'photoData')} alt="Фото страви"/>}<div className="hub-record-body"><strong>{x.title}</strong><div className="hub-meta">{readable(fieldText(x,'date'))}{x.duration?` · ${x.duration} хв`:''}{x.kg?` · ${fieldText(x,'kg')} кг`:''}{x.distance?` · ${x.distance} км`:''}{x.calories?` · ${x.calories} ккал`:''}</div>{['exercises','practice','note','content'].map(k=>x[k]?<p key={k} className="hub-record-detail">{fieldText(x,k)}</p>:null)}</div><Actions onEdit={()=>edit.open(tab,x)} onRemove={()=>void edit.remove(tab,x.id)}/></>}/>{!logs.length&&<Empty icon={kind==='fitness'?<Dumbbell size={26}/>:<Crosshair size={26}/>} title="Тут поки порожньо" body="Запиши перше тренування або створіть новий план із AI."/>}</section>
 <section className="hub-surface hub-ai-side"><div className="hub-ai-symbol"><Sparkles size={20}/></div><h2>AI-тренер</h2><p>Попроси програму скласти тижневу програму, урізноманітнити доріжку або допомогти з харчуванням. Вона пропонує — ти вирішуєш.</p><textarea rows={4} placeholder={tab==='meals'?'Склади збалансований приклад харчування на тиждень...':kind==='cs2'?'Допоможи підсумувати мою статистику CS2 за останні дні...' :'План вправ вдома без спортзалу та ходьби на моїй доріжці...' } value={query} onChange={e=>setQuery(e.target.value)}/><button className="button primary wide" disabled={loading||!snapshot.hasKey} onClick={()=>void askAI()}>{loading?<LoaderCircle size={16}/>:<Sparkles size={16}/>} {loading?'Готуємо рекомендацію…':'Запропонувати план'}</button>{!snapshot.hasKey&&<p className="hub-notice">Спочатку підключи OpenAI API в налаштуваннях.</p>}{advice&&<div className="hub-ai-result"><pre>{advice}</pre><button className="button outline" onClick={()=>void saveAdvice()}><Save size={15}/> Зберегти після перевірки</button></div>}<small className="hub-health-note">Це інструмент планування, а не медична консультація. Не використовуй рекомендації для екстремальних дієт чи навантажень.</small></section></div>
 {kind==='fitness'&&recent.length>1&&<section className="hub-surface"><h2>Історія ваги</h2><div className="hub-weight-chart">{recent.map(x=><div key={x.id}><strong>{fieldText(x,'kg')} кг</strong><div className="hub-weight-bar" style={{height:`${Math.max(25,Number(x.kg||0)/Math.max(...recent.map(z=>Number(z.kg)||1))*130)}px`}}/><small>{readable(fieldText(x,'date'))}</small></div>)}</div></section>}{edit.editorNode}</div>;
}

